window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-9701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1183 na letra δ · nº geral 9701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ép. 3a sing. διέσσυτο) 1 lançar-se para além de ou através de; transpor de um salto, ac. ou gen. 2 lançar-se; saltar.</p></section></article>\n<article id=\"entry-dgp-9702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασημαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1184 na letra δ · nº geral 9702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασημανῶ, aor. διεσήμηνα) 1 fazer compreender claramente; indicar claramente algo, ac., a alguém, dat. 2 indicar por meio de sinal; sinalizar 3 manifestar-se por sinais ♦ méd. 4 observar as características de; distinguir por sinais; reconhecer por sinais, ac. 5 aprovar; aplaudir.</p></section></article>\n<article id=\"entry-dgp-9703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάσημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1185 na letra δ · nº geral 9703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 claro; distinto; agudo 2 notável; eminente ♦ διάσημα adv. 3 com gritos agudos. 〈διά, σῆμα〉</p></section></article>\n<article id=\"entry-dgp-9704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασήπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1186 na letra δ · nº geral 9704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer apodrecer; putrefazer 2 perf. estar completamente podre ♦ pas. 3 apodrecer.</p></section></article>\n<article id=\"entry-dgp-9705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιάσια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1187 na letra δ · nº geral 9705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">festas de Zeus, em Atenas. 〈∆ιός〉</p></section></article>\n<article id=\"entry-dgp-9706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1188 na letra δ · nº geral 9706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">assobiar com força.</p></section></article>\n<article id=\"entry-dgp-9707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασιλλαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1189 na letra δ · nº geral 9707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διεσίλλαινον) ridicularizar; rir-se de; pôr em ridículo, ac.</p></section></article>\n<article id=\"entry-dgp-9708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασιωπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1190 na letra δ · nº geral 9708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασιωπήσομαι) 1 guardar silêncio; ficar silencioso 2 manter sob silêncio; calar, ac.</p></section></article>\n<article id=\"entry-dgp-9709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκαλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1191 na letra δ · nº geral 9709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sachar; revolver.</p></section></article>\n<article id=\"entry-dgp-9710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1192 na letra δ · nº geral 9710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">διασκαλεύω.</p></section></article>\n<article id=\"entry-dgp-9711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1193 na letra δ · nº geral 9711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escavar; abrir uma brecha em, gen.</p></section></article>\n<article id=\"entry-dgp-9712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκαριφάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1194 na letra δ · nº geral 9712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arranhar ♦ méd. (inf. aor. διασκαρι­φήσασθαι) 2 sapar 3 arruinar; destruir.</p></section></article>\n<article id=\"entry-dgp-9713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκεδάννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1195 na letra δ · nº geral 9713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασκεδῶ, aor. διεσκέδασα etc.) 1 dispersar 2 licenciar (um exército) 3 separar; desligar (a alma) 4 desjuntar; destruir; aniquilar 5 rejeitar ♦ pas. 6 (notícia) difundir-se; espalhar-se.</p></section></article>\n<article id=\"entry-dgp-9714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκεδῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1196 na letra δ · nº geral 9714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de διασκεδάννυμι.</p></section></article>\n<article id=\"entry-dgp-9715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκέπτομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1197 na letra δ · nº geral 9715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασκεψάσω etc.) 1 examinar por todos os lados; examinar a fundo 2 olhar ao redor; prestar atenção.</p></section></article>\n<article id=\"entry-dgp-9716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκευάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1198 na letra δ · nº geral 9716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασκευάσω etc.) 1 organizar; pôr em ordem, ac. 2 revestir; disfarçar com vestes alguém, ac., em, εἰς e ac. 3 preparar alguém, ac., para algo, εἰς e ac.: διασκευάζειν τινὰ εἰς τὴν πρᾶξιν plut. preparar uma pessoa para a ação ♦ méd. 4 preparar-se para algo, εἰς e ac. 5 tomar providências junto a alguém, πρός e ac.: δ. πρὸς τοὺς δικαστάς xen. tomar providências junto aos juízes, i.e., tentar corrompê-los 6 dispor de, ac.</p></section></article>\n<article id=\"entry-dgp-9717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκευή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1199 na letra δ · nº geral 9717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de construir; construção 2 preparação 3 elaboração ou revisão (de texto) 4 manipulação (de medicamento) 5 montagem (de espetáculo) 6 equipamento; petrechos 7 vestimenta 8 frase elaborada.</p></section></article>\n<article id=\"entry-dgp-9718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάσκεψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1200 na letra δ · nº geral 9718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inspeção; exame 2 pl. questões para examinar; questões.</p></section></article>\n<article id=\"entry-dgp-9719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1201 na letra δ · nº geral 9719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 preparar 2 adornar alguém 3 exercitar; adestrar alguém 4 praticar; pôr em prática ♦ méd. 5 exercitar-se. 〈διά, ἀσκέω〉</p></section></article>\n<article id=\"entry-dgp-9720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκηνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1202 na letra δ · nº geral 9720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 retirar-se para seu acampamento, para sua tenda 2 dispersar-se em direção a cada tenda 3 deixar a tenda.</p></section></article>\n<article id=\"entry-dgp-9721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκηνητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1203 na letra δ · nº geral 9721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διασκηνέω.</p></section></article>\n<article id=\"entry-dgp-9722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκηνόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1204 na letra δ · nº geral 9722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 erguer tendas de espaço em espaço; ter acampamentos isolados; acampar 2 separar-se para voltar às tendas ♦ pas. 3 estar disposto em tendas.</p></section></article>\n<article id=\"entry-dgp-9723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκίδνημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1205 na letra δ · nº geral 9723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">διασκεδάννυμι.</p></section></article>\n<article id=\"entry-dgp-9724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκιρτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1206 na letra δ · nº geral 9724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saltar.</p></section></article>\n<article id=\"entry-dgp-9725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκοπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1207 na letra δ · nº geral 9725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 examinar com cuidado; observar bem; estudar algo ou alguém, ac. 2 examinar bem ao redor de si ♦ méd. 3 examinar com cuidado.</p></section></article>\n<article id=\"entry-dgp-9726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακοπιάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1208 na letra δ · nº geral 9726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 examinar; espreitar; espiar 2 discernir; distinguir. 〈διά, σκοπιά〉</p></section></article>\n<article id=\"entry-dgp-9727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκορπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1209 na letra δ · nº geral 9727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. dissipar; dispersar.</p></section></article>\n<article id=\"entry-dgp-9728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασκώπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1210 na letra δ · nº geral 9728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 zombar; gracejar de, ac. ♦ méd. 2 trocar gracejos mútuos: ταῦτα μὴν δὴ οὕτω διεσκώπτοντο xen. trocaram entre si tais gracejos.</p></section></article>\n<article id=\"entry-dgp-9729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1211 na letra δ · nº geral 9729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">limpar; lavar; enxaguar.</p></section></article>\n<article id=\"entry-dgp-9730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασμήχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1212 na letra δ · nº geral 9730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enxugar bem; limpar bem 2 retirar limpando.</p></section></article>\n<article id=\"entry-dgp-9731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασοβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1213 na letra δ · nº geral 9731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dispersar assustando; afugentar 2 sacudir; agitar; excitar.</p></section></article>\n<article id=\"entry-dgp-9732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασόβησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1214 na letra δ · nº geral 9732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trepidação 2 inquietação; agitação. 〈διασοβέω〉</p></section></article>\n<article id=\"entry-dgp-9733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπαθάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1215 na letra δ · nº geral 9733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desperdiçar; dissipar ♦ méd. 2 espoliar.</p></section></article>\n<article id=\"entry-dgp-9734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπαρακτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1216 na letra δ · nº geral 9734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">posto em pedaços; despedaçado. 〈διασπαράσσω〉</p></section></article>\n<article id=\"entry-dgp-9735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπαράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1217 na letra δ · nº geral 9735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. διασπαράξω etc.) 1 colocar em pedaços; despedaçar 2 despedaçar com palavras 3 forçar; dilatar.</p></section></article>\n<article id=\"entry-dgp-9736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπαρείς</h1><div class=\"entry-meta\"><span>DGP · ordem 1218 na letra δ · nº geral 9736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. de διασπείρω.</p></section></article>\n<article id=\"entry-dgp-9737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάσπασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1219 na letra δ · nº geral 9737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separação violenta; arrancamento 2 separação; brecha; lacuna. 〈διασπάω〉</p></section></article>\n<article id=\"entry-dgp-9738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάσπασμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1220 na letra δ · nº geral 9738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separação; lacuna; vazio 2 ato de arrancar. 〈διασπάω〉</p></section></article>\n<article id=\"entry-dgp-9739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1221 na letra δ · nº geral 9739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 afastamento; dispersão 2 lacuna; interrupção 3 desordem. 〈διασπάω〉</p></section></article>\n<article id=\"entry-dgp-9740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1222 na letra δ · nº geral 9740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασπάσω etc.) 1 separar com força; afastar uma pessoa, ac., de outra, ac. ou ἀπό e gen. 2 romper com força; quebrar; cortar, ac. 3 arruinar; subverter; violar ♦ méd. 4 fazer em pedaços .</p></section></article>\n<article id=\"entry-dgp-9741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1223 na letra δ · nº geral 9741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασπερῶ; pas. aor.2 διεσπάρην, perf. διέσπαρμαι) 1 atirar para todos os lados; dispersar; espalhar; difundir 2 distribuir 3 desperdiçar.</p></section></article>\n<article id=\"entry-dgp-9742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπλεκόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1224 na letra δ · nº geral 9742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. pas. fem. διεσπλεκωμένη) praticar sexo até o esgotamento.</p></section></article>\n<article id=\"entry-dgp-9743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασπορά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1225 na letra δ · nº geral 9743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dispersão 2 bíbl. diáspora. 〈διασπείρω〉</p></section></article>\n<article id=\"entry-dgp-9744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διᾴσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1226 na letra δ · nº geral 9744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαΐσω.</p></section></article>\n<article id=\"entry-dgp-9745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστάς, διαστάν</h1><div class=\"entry-meta\"><span>DGP · ordem 1227 na letra δ · nº geral 9745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de διΐστημι.</p></section></article>\n<article id=\"entry-dgp-9746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστασιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1228 na letra δ · nº geral 9746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separar em facções; dividir; desunir 2 estar em discórdia; estar em dissentimento com alguém, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-9747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάστασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1229 na letra δ · nº geral 9747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de separar; separação; divisão 2 causa de divisão; motivo de dissensão 3 afastamento; separação; divórcio 4 distância; intervalo; intervalo musical 5 contraste; diferença 6 diferença de opiniões; dissentimento. 〈διΐστημι〉</p></section></article>\n<article id=\"entry-dgp-9748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστατικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1230 na letra δ · nº geral 9748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que separa; que dissolve 2 que desune; que leva à discórdia. 〈διάστατος〉</p></section></article>\n<article id=\"entry-dgp-9749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστατός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1231 na letra δ · nº geral 9749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 divisível 2 que tem extensão, dimensão; estendido (no espaço) 3 presa de dissensões; desunido. 〈διΐστημι〉</p></section></article>\n<article id=\"entry-dgp-9750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασταυρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1232 na letra δ · nº geral 9750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3a sing. διεσταύρου) munir com paliçadas; fortificar.</p></section></article>\n<article id=\"entry-dgp-9751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστείχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1233 na letra δ · nº geral 9751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διέστιχον) 1 andar através; atravessar; percorrer, ac. ou gen. 2 seguir seu caminho; caminhar.</p></section></article>\n<article id=\"entry-dgp-9752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1234 na letra δ · nº geral 9752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαστελῶ, aor. διέστειλα, perf. διέσταλκα; pas. fut. διασταλήσομαι, aor.2 διεστάλην) 1 separar 2 abrir: τὸ στόμα luc. entreabrir a boca 3 cortar; fender 4 separar; dispersar: τὰ νέφη plut. dissipar as nuvens 5 dilatar 6 diferenciar; distinguir uma coisa, ac., de outra, gen. 7 definir com exatidão; precisar: δ. τὰ λεγόμενα plat. precisar os enunciados 8 proferir; pronunciar ♦ at. intr. e méd. 9 estar em desacordo com; diferir; discrepar de alguém, πρός e ac. ♦ méd. 10 dar um encargo; dar ordens; prescrever a, dat. 11 admoestar; advertir alguém, dat., de algo, gen. ♦ méd. pas. 12 dispersar-se; expandir-se 13 (pulmões) dilatar-se.</p></section></article>\n<article id=\"entry-dgp-9753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάστημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1235 na letra δ · nº geral 9753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 intervalo; distância; espaço 2 in­tervalo de tempo; trégua 3 diferença 4 Gram. relação de dois termos 5 extensão; dimensão 6 distinção (do estilo) 7 Geom. raio (de círculo). 〈διΐστημι〉</p></section></article>\n<article id=\"entry-dgp-9754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1236 na letra δ · nº geral 9754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διΐστημι.</p></section></article>\n<article id=\"entry-dgp-9755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστήτην</h1><div class=\"entry-meta\"><span>DGP · ordem 1237 na letra δ · nº geral 9755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 ind. 3a dual ép. de διΐστημι.</p></section></article>\n<article id=\"entry-dgp-9756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1238 na letra δ · nº geral 9756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διέστιξα) 1 separar com sinais de pontuação; pontuar 2 distinguir 3 pontilhar.</p></section></article>\n<article id=\"entry-dgp-9757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστίλβω</h1><div class=\"entry-meta\"><span>DGP · ordem 1239 na letra δ · nº geral 9757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">brilhar; resplandecer.</p></section></article>\n<article id=\"entry-dgp-9758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστοιβάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1240 na letra δ · nº geral 9758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interpor; intercalar.</p></section></article>\n<article id=\"entry-dgp-9759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστοιχίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1241 na letra δ · nº geral 9759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dispor em fileiras.</p></section></article>\n<article id=\"entry-dgp-9760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστολή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1242 na letra δ · nº geral 9760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. dilatação; diástole 2 ação de separar; ação de fender; separação 3 fenda 4 distinção; diferenciação 5 explicação; relato minucioso 6 Gram. separação por vírgula. 〈διαστέλλω〉</p></section></article>\n<article id=\"entry-dgp-9761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστρατηγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1243 na letra δ · nº geral 9761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exercer a função de general; ser estratego 2 conduzir; dirigir como general 3 usar como estratagema, ac. 4 em Roma, chegar ao fim de sua função como pretor.</p></section></article>\n<article id=\"entry-dgp-9762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστρεβλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1244 na letra δ · nº geral 9762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(2a sing. aor. διεστρέβλωσας) torturar.</p></section></article>\n<article id=\"entry-dgp-9763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1245 na letra δ · nº geral 9763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαστρέψω etc.; pas. fut.2 διασ­τραφήσομαι, aor.2 διεστράφην, perf. διέστραμμαι) 1 fazer virar para diversos lados; torcer: δ. τὰ σώματα xen contorcer os corpos, τὰ ὄμματα διαστρέφεσθαι ser estrábico 2 virar para outro lado; desviar; inverter 3 perverter; distorcer : δ. τοὺς νόμους is. distorcer as leis, δ. τὸν δικαστήν artt. corromper o juiz, διαστραφῆναι τὴν διάνοιαν luc. ter o espírito às avessas 4 mudar; desviar: ἴχνος τὸ πρόσθεν οὐ διαστρέψω φρενῶν ésql. não me desviarei das pegadas já impressas por minha mente.</p></section></article>\n<article id=\"entry-dgp-9764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστροβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1246 na letra δ · nº geral 9764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançar-se impetuosamente através, ac.</p></section></article>\n<article id=\"entry-dgp-9765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαστροφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1247 na letra δ · nº geral 9765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 torção; distorção; ruptura por torção 2 deslocamento 3 deterioração; perversão. 〈διαστρέφω〉</p></section></article>\n<article id=\"entry-dgp-9766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάστροφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1248 na letra δ · nº geral 9766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 torcido; contorcido; torto 2 disforme 3 corrompido; perverso. 〈διαστρέφω〉</p></section></article>\n<article id=\"entry-dgp-9767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασυγχέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1249 na letra δ · nº geral 9767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">confundir inteiramente; confundir.</p></section></article>\n<article id=\"entry-dgp-9768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασυνίστημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1250 na letra δ · nº geral 9768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 demonstrar claramente; fazer compreender ou conhecer claramente ♦ méd. 2 prescrever-se a si mesmo; recomendar-se a si mesmo.</p></section></article>\n<article id=\"entry-dgp-9769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασύρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1251 na letra δ · nº geral 9769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. διασέσυρκα) 1 puxar; estirar 2 puxar com força; despedaçar 3 denegrir; ridicularizar 4 distender-se.</p></section></article>\n<article id=\"entry-dgp-9770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασφάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1252 na letra δ · nº geral 9770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 pas. διεσφάλην) 1 perturbar; subverter 2 fazer desviar ♦ pas. 3 desviar-se; frustrar-se em, gen., dat. ou ἐν e dat.: δ. τῆς συμμαχίας ésqn. não conseguir a aliança, δ. τῆς ἀληθείας d.s. afastar-se da verdade, δ. τῇ προνοίᾳ pol. enganar-se em sua previsão, δ. ἐν πράξεσι plut. falhar em suas ações.</p></section></article>\n<article id=\"entry-dgp-9771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασφάξ, άγος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1253 na letra δ · nº geral 9771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 precipício 2 divisão dos vasos sangüíneos 3 cavidade. 〈διασφάττω〉</p></section></article>\n<article id=\"entry-dgp-9772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασφενδονάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1254 na letra δ · nº geral 9772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lançar com um funda 2 desmembrar ♦ pas. 3 receber uma saraivada de projéteis.</p></section></article>\n<article id=\"entry-dgp-9773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασχηματίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1255 na letra δ · nº geral 9773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 moldar com arte; moldar ♦ méd. 2 modelar 3 ornar.</p></section></article>\n<article id=\"entry-dgp-9774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1256 na letra δ · nº geral 9774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διέσχισα) 1 fender; dilacerar 2 separar; afastar; dividir.</p></section></article>\n<article id=\"entry-dgp-9775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διασῴζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1257 na letra δ · nº geral 9775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διασώσω etc.) 1 retirar são e salvo alguém, ac., de, ἐκ e gen.: δ. τινὰ ἐκ κινδύνων isócr. salvar alguém tirando-o do perigo 2 conservar intacto, ac. 3 bíbl. levar a bom porto; guiar 4 bíbl. levar à salvação 5 conservar fielmente; preservar: δ. τὰ παλαιά isócr. preservar os antigos costumes 6 conservar na lembrança algo, ac. ♦ méd. 7 salvar do perigo; resgatar, ac. 8 conservar com cuidado; salvaguardar algo, ac. ♦ pas. 9 chegar são e salvo a, πρός ou εἰς e ac. 10 recuperar-se de uma doença.</p></section></article>\n<article id=\"entry-dgp-9776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαταγείς</h1><div class=\"entry-meta\"><span>DGP · ordem 1258 na letra δ · nº geral 9776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. de διατάσσω.</p></section></article>\n<article id=\"entry-dgp-9777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαταγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1259 na letra δ · nº geral 9777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. ordem; prescrição. 〈διατάσσω〉</p></section></article>\n<article id=\"entry-dgp-9778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάταγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1260 na letra δ · nº geral 9778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prescrição; édito. 〈διατάσσω〉</p></section></article>\n<article id=\"entry-dgp-9779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάταξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1261 na letra δ · nº geral 9779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disposição; colocação em ordem; distribuição; arranjo 2 mandamento; ordem 3 disposição de ânimo 4 disposição testamentária; convenção; pacto 5 constituição 6 regra; regulamento. 〈διατάσσω〉</p></section></article>\n<article id=\"entry-dgp-9780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαταράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1262 na letra δ · nº geral 9780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. διαταράξω etc.) desarrumar; perturbar; colocar em confusão; subverter.</p></section></article>\n<article id=\"entry-dgp-9781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαταραχή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1263 na letra δ · nº geral 9781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desordem; perturbação; desarranjo. 〈διαταράσσω〉</p></section></article>\n<article id=\"entry-dgp-9782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάτασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1264 na letra δ · nº geral 9782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distensão; dilatação 2 alongamento de membro fraturado 3 tensão; esforço; tensão dos músculos 4 contenda; disputa. 〈διατείνω〉</p></section></article>\n<article id=\"entry-dgp-9783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1265 na letra δ · nº geral 9783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. διατάξω etc.) 1 colocar em ordem; dispor rigorosamente: δ. ἀνθρώποισι νόμον hes. fixar uma lei para os homens 2 Mil. formar; colocar em formação; alinhar o exército 3 distribuir; repartir; atribuir como função algo, ac., a alguém, dat.: δ. τοὺς μὲν οἰκίας οἰκοδομέειν, τοὺς δὲ δορυφόρους εἶναι her. atribuir a uns a função de construir casas e a outros a de servir como lanceiros ♦ at. e méd. 4 regulamentar por testamento 5 tomar disposições para que; ordenar; mandar, inf. ♦ méd. 6 arranjar para si; classificar 7 comprometer-se a, inf. fut. 8 tomar disposições testamentárias a respeito de, περί e gen. 9 intr. colocar-se cada um em seu posto de combate; alinhar-se: διαταξάμενοι tendo-se colocado em fileiras.</p></section></article>\n<article id=\"entry-dgp-9784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαταφρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1266 na letra δ · nº geral 9784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">proteger com um fosso.</p></section></article>\n<article id=\"entry-dgp-9785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαταχθείς</h1><div class=\"entry-meta\"><span>DGP · ordem 1267 na letra δ · nº geral 9785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.1 pas. de διατάσσω.</p></section></article>\n<article id=\"entry-dgp-9786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατείνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1268 na letra δ · nº geral 9786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διατενῶ etc.) 1 esticar com força; estirar; distender: δ. τόξον her. esticar um arco com força 2 estender; esticar; alongar: δ. τὰς χεῖρας ἐπὶ τὰ λεκάνια xen. estender as mãos para as travessas ♦ at. e méd. 3 estender a caminhada; prosseguir até, πρός e ac.: διέτεινε πρὸς Γάζαν pol. prosseguia para Gaza 4 estender-se (no espaço); alongar-se: τὰ ὄρη Πυρηναῖα διατείνει ἀπὸ τῆς καθ᾽ ἡμᾶς θαλάττης ἕως εἰς τὴν ἐκτός pol. os Pirineus estendem-se a partir de nosso mar (Mediterrâneo) até o mar exterior (Atlântico) 5 estender-se (no tempo); durar: διετείνει ταῦτα διὰ παντὸς τοῦ Βίου artt. isso se estende por toda a vida 6 concernir a alguém ou algo, πρός e ac. ♦ méd. 7 manter em riste: διετείνοντο τὰ βέλεα ὡς ἀπήσοντες her. mantinham em riste as setas como se fossem lançá-las, διατεινάμενοι οἱ μὲν τὰ παλτὰ, οἱ δὲ τὰ τόξα xen. uns egurando em riste suas lanças e outros, seus arcos 8 ficar hirto; entesar-se: διατείνῃ καὶ βοᾷς luc. tu te entesas e gritas 9 esforçar-se para, inf.: δ. τὰ κάλλιστα πράττειν artt. esforçar-se para fazer o que há de mais belo 10 impedir de, μή e inf.: διετείνατο αὐτὸν μὴ εἰσελθεῖν εἰς ὑμᾶς ant. impediram-no de chegar até vós 11 sustentar energicamente; afirmar com tenacidade uma opinião, ac. ou or. conj. (ὅτι, ὡς): οὐκ αὐτὸς εἰδέναι τἀληθὲς ὑπὲρ τοὺς ἄλλους διατείνομαι luc. não pretendo conhecer a verdade mais que os outros.</p></section></article>\n<article id=\"entry-dgp-9787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατειχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1269 na letra δ · nº geral 9787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διατειχιῶ etc.) separar com um muro ou como se fosse com um muro: δ. τὴν πόλιν ἀπὸ τῆς ἄκρας pol. murar a cidade separando-a da cidadela, διατετείχισται ἡ ἱστορία πρὸς τὸ ἐγκώμιον luc. a história está separada do elogio como por um muro.</p></section></article>\n<article id=\"entry-dgp-9788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατείχισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1270 na letra δ · nº geral 9788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lugar fortificado; espaço fortificado 2 muro de fortificação ou de separação. 〈διατειχίζω〉</p></section></article>\n<article id=\"entry-dgp-9789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατελέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1271 na letra δ · nº geral 9789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. át. διατελῶ, jôn. διατελέσω etc.) 1 levar a termo; acabar; completar: δ. ὁδόν xen. concluir um trajeto, διατετελεκὼς τὰ ἐν τοῖς ἐφήβοις δέκα ἔτη xen. tendo completado os dez anos de estudo entre os jovens 2 levar a cabo; realizar; cumprir: δ. χάριν eur. realizar um favor 3 continuar; seguir; manter: διατέλει ὥσπερ ἤρξω plat. continua como começaste, διετέλει χρώμενος τῇ κορύνῃ plut. continuou usando a clava 4 permanecer; ficar; manter-se: δ. ἐν θαλάττῃ artt. permanecer no mar 5 mostrar-se sempre; viver; continuar a ser de determinado modo, com predic.: ἀνυπόδητός τε καὶ ἀχίτων διατελεῖς xen. vives descalço e sem túnica 6 passar a vida a; não cessar de, part.: τυραννῶν τὸν βίον διετέλεσεν isócr. permaneceu tirano até o fim de sua vida, τὸ λοιπὸν βίον καθεύδοντες διατελοῖτε ἄν plat. passaríeis o resto da vida dormindo.</p></section></article>\n<article id=\"entry-dgp-9790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατελής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1272 na letra δ · nº geral 9790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contínuo; incessante; perene; permanente.</p></section></article>\n<article id=\"entry-dgp-9791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατέμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1273 na letra δ · nº geral 9791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διατεμῶ, aor.2 διέταμον etc.) 1 cortar em dois; cortar de um lado a outro; fender; separar 2 desunir.</p></section></article>\n<article id=\"entry-dgp-9792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατεταμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1274 na letra δ · nº geral 9792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com esforço; energicamente.</p></section></article>\n<article id=\"entry-dgp-9793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατετραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1275 na letra δ · nº geral 9793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(2a sing. fut. jôn. διατετρανέεις) furar; perfurar; transpassar.</p></section></article>\n<article id=\"entry-dgp-9794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατήκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1276 na letra δ · nº geral 9794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer derreter; amolecer pelo calor 2 Medic. relaxar (intestinos) ♦ pas. 3 fundir-se; liqüefazer-se.</p></section></article>\n<article id=\"entry-dgp-9795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατηρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1277 na letra δ · nº geral 9795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vigiar atentamente; observar 2 guardar; manter fielmente ♦ méd. 3 observar; vigiar.</p></section></article>\n<article id=\"entry-dgp-9796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατηρητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1278 na letra δ · nº geral 9796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para conservar. 〈διατηρέω〉</p></section></article>\n<article id=\"entry-dgp-9797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατίθημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1279 na letra δ · nº geral 9797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαθήσω, aor.2 διέθην etc.) ativa 1 colocar em separado; distribuir; repartir 2 colocar em ordem; organizar; instituir 3 dirigir; conduzir algo, ac., de determinado modo, adv. 4 tratar alguém, ac., de determinado modo, adv. 5 colocar alguém, ac., em determinada disposição ou atitude de ânimo, adv., contra alguém, πρός e ac. 6 expor; recitar; declamar média 7 dispor para si; estabelecer 8 arranjar; compor 9 dispor de algo ou alguém, ac., de determinado modo 10 dar em testamento; fazer testamento 11 dispor de; vender 1 τὸ μὲν ἐπὶ δεξιά, τὸ δ᾽ ἐπ᾽ ἀριστερὰ δ. her. colocar uma metade [do corpo de uma criança] à direita e a outra, à esquerda, δ. οἶνον εἰς ὀστράκια artt. repartir o vinho em conchas 2 τοὺς ἀγῶνας δ. xen. instituir os concursos 3 καλὸν πρᾶγμα κακῶς δ. dem. conduzir mal um bom negócio, κράτιστα δ. τὰ τοῦ πολέμου tuc. conduzir da melhor maneira possível as questões bélicas, τὰ κατὰ τὰς Γαλλίας ἄριστα διαθείς her. após ter organizado muito bem os negócios gauleses 4 ἀνόμως τὴν πόλιν δ. isócr. tratar a cidade de maneira contrária às leis, τοιαῦτα με διατίθης luc. tratas-me assim 5 δ. τινὰ ἀπίστως πρὸς ἡμᾶς αὐτούς dem. predispor alguém a desconfiar de nós, δ. τὸν ἀκροατήν πως artt. predispor de alguma maneira o ouvinte 6 κακῶς ποιήματα δ. plat. recitar mal poemas 7 ἢν μὴ διάθωνταί γ᾽ οἵδε διαθήκην ἐμοί ar. se não fazem um pacto comigo, διαθέμενοι περὶ τούτων νόμους plat. tendo estabelecido leis a esse respeito, δ. τὴν ἀποδημίαν and. organizar a partida, διαθήκας διατίθεσθαι lís. fazer seu testamento 8 δύνανται τὴν ἔριν συμφερόντως ἀλλήλοις διατί­θεσθαι xen. podem ajustar a contenda com mútua vantagem, δ. δημηγορίαν, ἔπαινον d.h. compor um discurso, um elogio 9 τὴν θυγατέρα ταύτην ἐπιτρέπω σοι διαθέσθαι ὅπως ἂν σὺ βούλῃ xen. entrego-te esta filha para que dela disponhas como quiseres, τἀμὰ διαθοῦ πάντα ὡς τὰ σαυτοῦ dem. disponha de todos meus bens como se fossem teus, εἰς καλὸν τὴν ἐν τῷ περιπάτῳ διατίθεται σχολήν luc. usa bem o tempo livre da caminhada 10 ὁ νόμος οὐ διαθέσθαι ἐᾷ τάδε dem. a lei não permite dispor isso em testamento, ἄκυρον εἶναι διατίθεσθαι plat. não ter direito de fazer testamento 11 ἐπεὰν διαθέωσι τὸν φόρτον her. depois que dispuserem a carga [para a venda].</p></section></article>\n<article id=\"entry-dgp-9798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατιμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1280 na letra δ · nº geral 9798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. pas. 3a sing. διατετίμηται) 1 julgar ♦ méd. 2 avaliar.</p></section></article>\n<article id=\"entry-dgp-9799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατινάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1281 na letra δ · nº geral 9799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διετίναξα) 1 sacudir; chocalhar; agitar 2 fazer desabar 3 despedaçar; quebrar.</p></section></article>\n<article id=\"entry-dgp-9800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατμήγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1282 na letra δ · nº geral 9800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.1 διέτμηξα, aor.2 διέτμαγον) 1 cortar inteiramente; fender 2 separar; distinguir ♦ méd. 3 sulcar (campo) ♦ pas. 4 separar-se; dispersar-se.</p></section></article>\n";
